// Best-effort HMAC verification. Django signs X-Signature = HMAC-SHA256(
// N8N_SHARED_SECRET, raw compact JSON body). NOTE: n8n's raw-body access varies
// by version, so this is observability-only and does NOT block delivery — enforce
// signatures with n8n native Header Auth or a network control in production.
const crypto = require('crypto');
const secret = $env.N8N_SHARED_SECRET || '';
const items = $input.all();
let headers = {};
try { headers = ($input.first().json.headers) || {}; } catch (e) {}
const sig = headers['x-signature'] || headers['X-Signature'] || '';
let raw = '';
try {
  const j = $input.first().json;
  raw = (typeof j.body === 'string') ? j.body : JSON.stringify(j.body != null ? j.body : j);
} catch (e) { raw = ''; }
let valid = false;
try {
  if (secret && sig && raw) {
    const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
    valid = (expected.length === sig.length) &&
            crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  }
} catch (e) { valid = false; }
return items.map(it => ({ json: Object.assign({}, it.json, { _signature_valid: valid }) }));

// Multilingual cart-recovery email.
const p = $input.first().json;
const lang = (p.language || 'en').toLowerCase();
const d = p.data || {};

const t = {
  en: { subject: 'You left something behind 👀', hi: `Hi ${d.first_name || ''},`, intro: 'Your cart is waiting for you. Complete your order before these items sell out!', items: 'Your items', cta: 'Return to my cart', thanks: 'See you soon — Glitchy.' },
  it: { subject: 'Hai dimenticato qualcosa 👀', hi: `Ciao ${d.first_name || ''},`, intro: 'Il tuo carrello ti aspetta. Completa l’ordine prima che questi articoli finiscano!', items: 'I tuoi articoli', cta: 'Torna al carrello', thanks: 'A presto — Glitchy.' },
  fr: { subject: 'Vous avez oublié quelque chose 👀', hi: `Bonjour ${d.first_name || ''},`, intro: 'Votre panier vous attend. Finalisez votre commande avant que ces articles ne partent !', items: 'Vos articles', cta: 'Retour à mon panier', thanks: 'À bientôt — Glitchy.' }
}[lang];
const L = t || { subject: 'You left something behind 👀', hi: `Hi ${d.first_name || ''},`, intro: 'Your cart is waiting for you.', items: 'Your items', cta: 'Return to my cart', thanks: 'See you soon — Glitchy.' };

const list = (d.items || []).map(it => `<li>${it.name}${it.variant ? ' – ' + it.variant : ''}${it.qty ? ' ×' + it.qty : ''}</li>`).join('');
const btn = d.cart_url ? `<p style="margin:18px 0"><a href="${d.cart_url}" style="background:#111;color:#fff;padding:10px 18px;text-decoration:none;border-radius:6px;display:inline-block">${L.cta}</a></p>` : '';
const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:auto;color:#222">
<h2 style="color:#111">${L.subject}</h2>
<p>${L.hi}</p>
<p>${L.intro}</p>
${list ? `<p><strong>${L.items}:</strong></p><ul>${list}</ul>` : ''}
${btn}
<p style="margin-top:20px;color:#666">${L.thanks}</p>
</div>`;

return [{ json: { to: p.recipient || d.email, subject: L.subject, html } }];
